    /// Recognizes speech in a video note or a voice note message
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> RecognizeSpeechAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("RecognizeSpeechAsync", typeof(RecognizeSpeech).FullName ?? "RecognizeSpeechAsync");

           try
           {
             return client.RecognizeSpeechAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
